triangle-kind:
def main(a, b, c):
    sides = sorted([a, b, c])
    x, y, z = sides
    if x <= 0 or x + y <= z:
        return 0
    if a == b == c:
        return 1
    if a == b or b == c or a == c:
        return 2
    return 3

isqrt:
def main(n):
    r = 0
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

is-prime:
def main(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

lcm:
def main(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return a * b // gcd(a, b)

allocate:
def main(remaining, requested, whole):
    if requested <= remaining:
        return (remaining - requested, requested, 0)
    if remaining == 0:
        return (remaining, 0, 2)
    if whole:
        return (remaining, 0, 3)
    return (0, remaining, 1)
